1	import type { State, ToolView } from "./types.ts";
2	import { toToolView } from "./tool-view.ts";
3	
4	export type BorrowResult =
5	  | { ok: true; tool: ToolView }
6	  | {
7	      ok: false;
8	      error: { code: "VALIDATION_ERROR" | "TOOL_NOT_FOUND" | "ALREADY_BORROWED"; message: string };
9	    };
10	
11	export function borrowTool(
12	  state: State,
13	  toolId: string,
14	  borrower: string | undefined,
15	  now: Date,
16	): { state: State; result: BorrowResult } {
17	  const trimmedBorrower = typeof borrower === "string" ? borrower.trim() : "";
18	  if (trimmedBorrower.length === 0) {
19	    return {
20	      state,
21	      result: {
22	        ok: false,
23	        error: { code: "VALIDATION_ERROR", message: "Bitte einen Namen angeben." },
24	      },
25	    };
26	  }
27	
28	  const tool = state.tools.find((candidate) => candidate.id === toolId);
29	  if (tool === undefined) {
30	    return {
31	      state,
32	      result: {
33	        ok: false,
34	        error: { code: "TOOL_NOT_FOUND", message: "Werkzeug nicht gefunden." },
35	      },
36	    };
37	  }
38	
39	  const existingLoan = state.loans.find((candidate) => candidate.toolId === toolId);
40	  if (existingLoan !== undefined) {
41	    return {
42	      state,
43	      result: {
44	        ok: false,
45	        error: { code: "ALREADY_BORROWED", message: "Dieses Werkzeug ist bereits ausgeliehen." },
46	      },
47	    };
48	  }
49	
50	  const newLoan = { toolId, borrower: trimmedBorrower, borrowedAt: now.toISOString() };
51	  const nextState: State = { tools: state.tools, loans: [...state.loans, newLoan] };
52	  return { state: nextState, result: { ok: true, tool: toToolView(tool, nextState.loans) } };
53	}
54

