1	import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
2	import path from "node:path";
3	import type { State } from "../domain/types.ts";
4	
5	export interface Repository {
6	  mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R>;
7	  getState(): State;
8	}
9	
10	function emptyState(): State {
11	  return { tools: [], loans: [] };
12	}
13	
14	async function readExistingState(dataFilePath: string): Promise<State | null> {
15	  let raw: string;
16	  try {
17	    raw = await readFile(dataFilePath, "utf8");
18	  } catch (err) {
19	    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
20	      return null;
21	    }
22	    throw err;
23	  }
24	  if (raw.trim().length === 0) {
25	    return null;
26	  }
27	  return JSON.parse(raw) as State;
28	}
