1	import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
2	import path from "node:path";
3	import type { State } from "../domain/types.ts";
4	
5	export interface Repository {
6	  mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R>;
7	  getState(): State;
8	}
9	
10	function emptyState(): State {
11	  return { tools: [], loans: [] };
12	}
13	
14	async function readExistingState(dataFilePath: string): Promise<State | null> {
15	  let raw: string;
16	  try {
17	    raw = await readFile(dataFilePath, "utf8");
18	  } catch (err) {
19	    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
20	      return null;
21	    }
22	    throw err;
23	  }
24	  if (raw.trim().length === 0) {
25	    return null;
26	  }
27	  return JSON.parse(raw) as State;
28	}
29	
30	async function writeStateAtomically(dataFilePath: string, state: State): Promise<void> {
31	  const dir = path.dirname(dataFilePath);
32	  await mkdir(dir, { recursive: true });
33	  const tempFilePath = path.join(dir, `.${path.basename(dataFilePath)}.${process.pid}.${Date.now()}.tmp`);
34	  await writeFile(tempFilePath, JSON.stringify(state, null, 2), "utf8");
35	  try {
36	    await rename(tempFilePath, dataFilePath);
37	  } catch (err) {
38	    await rm(tempFilePath, { force: true });
39	    throw err;
40	  }
41	}
42	
43	export async function createRepository(dataFilePath: string): Promise<Repository> {
44	  const existingState = await readExistingState(dataFilePath);
45	  let state: State = existingState ?? emptyState();
46	
47	  if (existingState === null) {
48	    await writeStateAtomically(dataFilePath, state);
49	  }
50	
51	  // Serializes mutate() calls: each call is chained onto the previous one,
52	  // so read -> decide -> write per call runs atomically with respect to others (AD-3).
53	  let queue: Promise<unknown> = Promise.resolve();
54	
55	  function mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R> {
56	    const task = queue.then(async () => {
57	      const { state: nextState, result } = fn(state);
58	      await writeStateAtomically(dataFilePath, nextState);
59	      state = nextState;
60	      return result;
61	    });
62	    queue = task.catch(() => {});
63	    return task;
64	  }
65	
66	  function getState(): State {
67	    return state;
68	  }
69	
70	  return { mutate, getState };
71	}
